import{z as l,x as s,o as e,c as p,q as n,j as t,D as E,d as B,s as o,S as A,b as i}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"共同价值与赢家诅咒","description":"","frontmatter":{"title":"共同价值与赢家诅咒","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/winner-curse.md","filePath":"econ/winner-curse.md","lastUpdated":1791063341000}'),d={name:"econ/winner-curse.md"};function m(c,a,h,D,F,u){const r=s("Mermaid");return e(),p("div",null,[a[2]||(a[2]=n('<h1 id="共同价值与赢家诅咒" tabindex="-1">共同价值与赢家诅咒 <a class="header-anchor" href="#共同价值与赢家诅咒" aria-label="Permalink to &quot;共同价值与赢家诅咒&quot;">​</a></h1><div class="epigraph"><p>赢得拍卖是坏消息：胜者的信号在所有人里最高，对共同价值的条件期望低于只凭自己信号时的估计；不遮挡就会买贵。</p><footer>—— 据 Wilson 的矿物权投标；Milgrom and Weber, A Theory of Auctions and Competitive Bidding, Econometrica, 1982</footer></div><p><a href="/econ/revenue-equivalence">上一课</a>在 IPV 正则下把标准拍卖的期望收入钉成同一条 \\(Q\\)。缺口是估值不再独立私有：物品有一块共同价值（油储、公司控制权），各人只持有有噪声的信号。此时「赢」本身更新信念，收入等价失败，英式与密封不再一样。本课钉赢家诅咒与关联，不把价格发现写成限价簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>矿物权模型：真实价值 \\(V\\) 对所有人相同（或高度关联），信号 \\(X_i=V+\\varepsilon_i\\)。若仍按 IPV 的一价均衡去叫，赢的时候 \\(\\mathbb{E}[V\\mid X_i=x,\\,\\text{赢}]\\) 低于 \\(\\mathbb{E}[V\\mid X_i=x]\\)——因为赢意味着别人的信号都更低。这就是赢家诅咒：胜者系统性地高估。理性投标必须在叫价里预先扣掉这块坏消息，遮挡比 IPV 更狠。</p><p><span class="marginnote">数字实例：油田真实价值约 1000 万，你的信号也是 1000 万，但每个信号带 ±100 万的噪声。若按「我的信号＝价值」出价 1000 万，赢时往往说明所有人的噪声都朝下——给定赢的条件期望可能只有 850 万，你平均买贵 150 万。</span></p><p>关联（affiliation，Milgrom–Weber）：信号与价值同向变动的强形式。关联下，对手叫得高是好消息。英式拍卖把对手的退出价公开，胜者在加价过程中不断更新；密封一价没有这条公开路径。联动原理：公开与价值关联的信息，能提高期望收入。故关联下英式期望收入 \\(\\ge\\) 二价 \\(\\ge\\) 一价（在对称模型的标准排序里）。</p><h3 id="诅咒不是「人变傻」" tabindex="-1">诅咒不是「人变傻」 <a class="header-anchor" href="#诅咒不是「人变傻」" aria-label="Permalink to &quot;诅咒不是「人变傻」&quot;">​</a></h3><p>诅咒是条件期望的会计：选择「赢」这个事件，截断了信号分布的下侧。幼稚投标用无条件估计，均衡投标用「给定赢」的估计。实验里常见过度叫价，那是对这条会计的偏离，不是定义本身。</p><p><span class="marginnote">Wilson 的完全竞争投标极限：人数极多时，叫价趋近真实 \\(V\\)，但有限 \\(n\\) 时诅咒必须进入策略。Milgrom–Weber 把英式、荷式、一价、二价放进同一关联结构里比较收入，IPV 是关联退化为独立的特例。</span></p><p>IPV 里赢不提供关于自己估值的新信息，因为 \\(v_i\\) 已是私有且独立。 共同价值里 \\(v_i\\) 还没被自己完全知道，赢是额外的似然比。 收入等价用的包络少了这项条件期望，所以推不出「同一 \\(Q\\) 则同一收入」。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：对称关联模型，风险中性。先写一价：叫价 \\(b(x)\\) 对「给定 \\(X_i=x\\) 且赢」的条件价值取期望再遮挡。再写英式：价格升到只剩两人时，公开退出史已经把下侧信号泄露，剩余策略接近「真实条件期望」。比较收入用联动：把密封里藏着的对手信息，部分搬到路径上。</p>',13)),(e(),t(A,null,{default:E(()=>[o(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IPV%5B%22IPV%EF%BC%9A%E8%B5%A2%E4%B8%8D%E6%9B%B4%E6%96%B0%E8%87%AA%E5%B7%B1%E7%9A%84%20v%22%5D%20--%3E%20RET%5B%22%E6%94%B6%E5%85%A5%E7%AD%89%E4%BB%B7%22%5D%0A%20%20CV%5B%22%E5%85%B1%E5%90%8C%20%2F%20%E5%85%B3%E8%81%94%E4%BB%B7%E5%80%BC%22%5D%20--%3E%20WC%5B%22%E8%B5%A2%20%3D%20%E5%9D%8F%E6%B6%88%E6%81%AF%22%5D%0A%20%20WC%20--%3E%20SHADE%5B%22%E5%8F%AB%E4%BB%B7%E5%BF%85%E9%A1%BB%E9%A2%84%E5%85%88%E6%89%A3%E5%87%8F%22%5D%0A%20%20AFF%5B%22%E5%85%B3%E8%81%94%20%2B%20%E5%85%AC%E5%BC%80%E9%80%80%E5%87%BA%22%5D%20--%3E%20LINK%5B%22%E8%8B%B1%E5%BC%8F%E6%94%B6%E5%85%A5%E5%8F%AF%E6%9B%B4%E9%AB%98%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[B("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"信息结构改的是「赢」这个事件的含义。IPV 下赢只是「我的私人数字最大」；共同价值下赢是「我的噪声最朝上」。理性人把这一似然比写进叫价，否则事后 \\(\\mathbb{E}[V-\\text{支付}\\mid\\text{赢}]\\lt 0\\)。英式把别人的信号逐步公开，胜者的条件期望在加价中被纠正，诅咒被部分保险；密封没有这条保险，叫价更保守或收入更低。",-1)),(e(),t(A,null,{default:E(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20BID%5B%22%E4%BD%A0%E8%B5%A2%E4%B8%8B%E6%8B%8D%E5%8D%96%22%5D%20--%3E%20INF%5B%22%E5%90%AB%E4%B9%89%EF%BC%9A%E6%89%80%E6%9C%89%E5%AF%B9%E6%89%8B%E7%9A%84%E4%BF%A1%E5%8F%B7%E9%83%BD%E6%AF%94%E4%BD%A0%E4%BD%8E%22%5D%0A%20%20INF%20--%3E%20TRU%5B%22%E4%BD%A0%E7%9A%84%E4%BF%A1%E5%8F%B7%E4%BD%8D%E4%BA%8E%E4%BA%BA%E7%BE%A4%E7%9A%84%E4%B8%8A%E4%BE%A7%22%5D%0A%20%20TRU%20--%3E%20NOISE%5B%22%E4%BF%A1%E5%8F%B7%E5%81%8F%E9%AB%98%E6%9B%B4%E5%8F%AF%E8%83%BD%E6%98%AF%E5%99%AA%E5%A3%B0%E6%9C%9D%E4%B8%8A%22%5D%0A%20%20NOISE%20--%3E%20CUT%5B%22%E5%AF%B9%20V%20%E7%9A%84%E6%9D%A1%E4%BB%B6%E6%9C%9F%E6%9C%9B%E4%BD%8E%E4%BA%8E%E5%8F%AA%E7%9C%8B%E8%87%AA%E5%B7%B1%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20CUT%20--%3E%20ACT%5B%22%E7%90%86%E6%80%A7%E5%8F%8D%E5%BA%94%EF%BC%9A%E5%8F%AB%E4%BB%B7%E9%A2%84%E5%85%88%E6%89%A3%E6%8E%89%E5%9D%8F%E6%B6%88%E6%81%AF%22%5D%0A%20%20ACT%20--%3E%20FAIL%5B%22%E4%B8%8D%E6%89%A3%20%E2%86%92%20%E4%BA%8B%E5%90%8E%E6%9C%9F%E6%9C%9B%E5%88%A9%E6%B6%A6%E4%B8%BA%E8%B4%9F%EF%BC%9A%E8%A2%AB%E8%AF%85%E5%92%92%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">术语翻译：条件期望就是「听到新消息后重新算的平均数」。先平均再看消息，与看完消息再平均，是两个不同的数；赢家诅咒说的就是这两个数的差——对胜者而言恒为负。</span></p><p>联动不是「公开越多越好」的空话：公开的必须与价值关联。公开无关噪声只增加混淆。这与道德风险里「合同只应依赖充足统计」同一逻辑，但本课的对象是拍卖信息结构，不是工资合同。</p><p>IPV 里赢不提供关于自己估值的新信息；共同价值里 \\(v_i\\) 还没被自己完全知道，赢是额外的似然比。 收入等价用的包络少了这项条件期望，所以推不出「同一 \\(Q\\) 则同一收入」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>纯共同价值是极限；多数拍卖是混合：私人使用价值加共同残值。非对称信号、胜者知道得更多（winner&#39;s curse 的镜像是「败者的羡慕」），排序可以改。风险厌恶、合谋、预算约束再叠加，Milgrom–Weber 的收入排序不必成立。</p><p>不要把赢家诅咒写成限价簿里知情交易者吃价差：那是做市存货与方向性私人信息，属于微观结构，不在本课。本课的价格是一次性拍卖叫价，没有连续簿。</p><p>后课默认：离开 IPV 后，赢是信息；关联下公开加价可以拉开收入。配置若变成双边配对、没有单物品叫价，要用稳定匹配，不是再写一条叫价函数。</p><h3 id="遮挡的两层不要混" tabindex="-1">遮挡的两层不要混 <a class="header-anchor" href="#遮挡的两层不要混" aria-label="Permalink to &quot;遮挡的两层不要混&quot;">​</a></h3><p>IPV 一价的遮挡是怕自己付多、怕没赢的概率权重；共同价值还要再扣「给定赢，\\(V\\) 更差」。两层可以同向，实证难分。油田租赁、公司并购是经典场景：胜者往往是信号最乐观的那一个。</p><p><span class="marginnote">直觉类比：英式拍卖像把对手的答卷一张张亮出来——有人 500 万退出，你立刻知道他的信号只有 500 万，自己的「偏乐观」被实时纠偏；密封拍卖人人把答卷扣在桌上，你只能按最悲观的假设自我打折，公开与保密直接改变你该出多少。</span></p><p><span class="marginnote">联动原理要求对称与关联；一旦信号结构非对称，公开信息也可能伤害卖家。本课只钉对称教具。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共同价值下，赢截断他人信号，条件期望低于事前估计。</li><li>理性叫价必须预先扣掉赢家诅咒；幼稚投标会买贵。</li><li>关联使英式的公开退出有价值，收入等价失败。</li><li>这不是限价簿价差；下一课把配置换成双边匹配。</li><li>出处：Wilson 矿物权投标；Milgrom and Weber, <em>Econometrica</em> 1982。</li></ul>',13))])}const C=l(d,[["render",m]]);export{b as __pageData,C as default};
